     1	package br.com.marealta.web;
     2	
     3	import br.com.marealta.ApiException;
     4	import br.com.marealta.model.*;
     5	import br.com.marealta.plan.RatePlan;
     6	import br.com.marealta.plan.RatePlans;
     7	import br.com.marealta.service.*;
     8	import com.fasterxml.jackson.core.JsonProcessingException;
     9	import com.fasterxml.jackson.databind.JsonNode;
    10	import com.fasterxml.jackson.databind.ObjectMapper;
    11	import com.fasterxml.jackson.databind.SerializationFeature;
    12	import io.javalin.Javalin;
    13	import io.javalin.http.Context;
    14	import java.nio.charset.StandardCharsets;
    15	import java.time.LocalDate;
    16	import java.time.YearMonth;
    17	import java.time.format.DateTimeParseException;
    18	import java.util.LinkedHashMap;
    19	import java.util.List;
    20	import java.util.Map;
    21	
    22	public class App {
    23	    private static final ObjectMapper JSON = new ObjectMapper()
    24	            .enable(SerializationFeature.WRITE_BIGDECIMAL_AS_PLAIN);
    25	
    26	    private final ReservationService reservations;
    27	    private final ReportService reports;
    28	
    29	    public App(ReservationService reservations, ReportService reports) {
    30	        this.reservations = reservations;
    31	        this.reports = reports;
    32	    }
    33	
    34	    public Javalin create() {
    35	        Javalin app = Javalin.create(cfg -> cfg.showJavalinBanner = false);
    36	
    37	        app.get("/rooms", ctx -> json(ctx, 200, reservations.rooms().stream().map(App::roomView).toList()));
    38	        app.post("/reservations", ctx -> json(ctx, 201, view(reservations.create(parseNew(ctx)))));
    39	        app.get("/reservations/{id}", ctx -> json(ctx, 200, view(reservations.get(id(ctx)))));
    40	        app.post("/reservations/{id}/confirmation", ctx -> json(ctx, 200, view(reservations.confirm(id(ctx)))));
    41	        app.post("/reservations/{id}/cancellation", ctx -> json(ctx, 200, view(reservations.cancel(id(ctx)))));
    42	        app.post("/reservations/{id}/check-in", ctx -> json(ctx, 200, view(reservations.checkIn(id(ctx)))));
    43	        app.post("/reservations/{id}/check-out", ctx -> json(ctx, 200, receiptView(reservations.checkOut(id(ctx)))));
    44	        app.get("/reservations/{id}/document", ctx -> json(ctx, 200, receiptView(reservations.document(id(ctx)))));
    45	        app.get("/messages", ctx -> json(ctx, 200, reservations.messages().stream().map(App::messageView).toList()));
    46	
    47	        app.get("/reports/occupancy", ctx -> csv(ctx, reports.occupancy(parseDate(ctx.queryParam("date"), "date"))));
    48	        app.get("/reports/revenue", ctx -> csv(ctx, reports.revenue(parseMonth(ctx.queryParam("month")))));
    49	
    50	        app.exception(ApiException.class, (e, ctx) -> error(ctx, e.status(), e.code(), e.getMessage()));
    51	        app.exception(Exception.class, (e, ctx) -> {
    52	            e.printStackTrace();
    53	            error(ctx, 500, "INTERNAL_ERROR", "Erro interno");
    54	        });
    55	        app.error(404, ctx -> {
    56	            if (ctx.result() == null || ctx.result().isEmpty()) error(ctx, 404, "NOT_FOUND", "Recurso não encontrado");
    57	        });
    58	        return app;
    59	    }
    60	
    61	    // ---- entrada ----
    62	
    63	    private static ReservationService.NewReservation parseNew(Context ctx) {
    64	        JsonNode body;
    65	        try {
    66	            body = JSON.readTree(ctx.bodyAsBytes());
    67	        } catch (java.io.IOException e) {
    68	            throw ApiException.invalid("O corpo da requisição não é um JSON válido");
    69	        }
    70	        if (body == null || !body.isObject()) throw ApiException.invalid("O corpo da requisição deve ser um objeto JSON");
    71	
    72	        JsonNode room = body.get("roomNumber");
    73	        if (room == null || !room.isIntegralNumber() || !room.canConvertToInt()) {
    74	            throw ApiException.invalid("roomNumber é obrigatório e deve ser um número inteiro");
    75	        }
    76	        String name = text(body, "guestName");
    77	        String email = text(body, "guestEmail");
    78	        String cpf = text(body, "guestCpf");
    79	        LocalDate in = parseDate(text(body, "checkIn"), "checkIn");
    80	        LocalDate out = parseDate(text(body, "checkOut"), "checkOut");
    81	        JsonNode g = body.get("guests");
    82	        if (g == null || !g.isIntegralNumber() || !g.canConvertToInt()) {
    83	            throw ApiException.invalid("guests é obrigatório e deve ser um número inteiro");
    84	        }
    85	        String planCode = text(body, "ratePlan");
    86	        RatePlan plan = RatePlans.find(planCode)
    87	                .orElseThrow(() -> ApiException.invalid("Plano de tarifa desconhecido: " + planCode));
    88	        if (!out.isAfter(in)) throw ApiException.invalid("A saída deve ser depois da entrada");
    89	        if (g.intValue() < 1) throw ApiException.invalid("É preciso pelo menos um hóspede");
    90	
    91	        JsonNode company = body.get("companyCode");
    92	        String companyCode = company != null && company.isTextual() ? company.textValue() : null;
    93	        return new ReservationService.NewReservation(room.intValue(), name, email, cpf, in, out, g.intValue(), plan, companyCode);
    94	    }
    95	
    96	    private static String text(JsonNode body, String field) {
    97	        JsonNode n = body.get(field);
    98	        if (n == null || !n.isTextual() || n.textValue().isBlank()) {
    99	            throw ApiException.invalid(field + " é obrigatório");
   100	        }
   101	        return n.textValue();
   102	    }
   103	
   104	    private static LocalDate parseDate(String s, String field) {
   105	        if (s == null) throw ApiException.invalid(field + " é obrigatório (formato AAAA-MM-DD)");
   106	        try {
   107	            return LocalDate.parse(s);
   108	        } catch (DateTimeParseException e) {
   109	            throw ApiException.invalid(field + " inválido, use o formato AAAA-MM-DD");
   110	        }
   111	    }
   112	
   113	    private static YearMonth parseMonth(String s) {
   114	        if (s == null) throw ApiException.invalid("month é obrigatório (formato AAAA-MM)");
   115	        try {
   116	            return YearMonth.parse(s);
   117	        } catch (DateTimeParseException e) {
   118	            throw ApiException.invalid("month inválido, use o formato AAAA-MM");
   119	        }
   120	    }
   121	
   122	    private static long id(Context ctx) {
   123	        String raw = ctx.pathParam("id");
   124	        try {
   125	            return Long.parseLong(raw);
   126	        } catch (NumberFormatException e) {
   127	            throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reserva " + raw + " não existe");
   128	        }
   129	    }
   130	
   131	    // ---- saída ----
   132	
   133	    private static void json(Context ctx, int status, Object body) {
   134	        try {
   135	            ctx.status(status).contentType("application/json; charset=utf-8")
   136	                    .result(JSON.writeValueAsBytes(body));
   137	        } catch (JsonProcessingException e) {
   138	            throw new IllegalStateException(e);
   139	        }
   140	    }
   141	
   142	    private static void csv(Context ctx, String body) {
   143	        ctx.status(200).contentType("text/csv; charset=utf-8").result(body.getBytes(StandardCharsets.UTF_8));
   144	    }
   145	
   146	    private static void error(Context ctx, int status, String code, String message) {
   147	        Map<String, Object> m = new LinkedHashMap<>();
   148	        m.put("error", code);
   149	        m.put("message", message);
   150	        json(ctx, status, m);
   151	    }
   152	
   153	    private static Map<String, Object> roomView(Room r) {
   154	        Map<String, Object> m = new LinkedHashMap<>();
   155	        m.put("number", r.number());
   156	        m.put("type", r.type());
   157	        m.put("capacity", r.capacity());
   158	        m.put("nightlyRate", r.nightlyRate());
   159	        return m;
   160	    }
   161	
   162	    private static Map<String, Object> view(Reservation r) {
   163	        Map<String, Object> m = new LinkedHashMap<>();
   164	        m.put("id", r.id());
   165	        m.put("roomNumber", r.roomNumber());
   166	        m.put("guestName", r.guestName());
   167	        m.put("guestEmail", r.guestEmail());
   168	        m.put("guestCpf", r.guestCpf());
   169	        m.put("checkIn", r.checkIn().toString());
   170	        m.put("checkOut", r.checkOut().toString());
   171	        m.put("guests", r.guests());
   172	        m.put("ratePlan", r.ratePlan());
   173	        m.put("nights", r.nights());
   174	        m.put("subtotal", r.subtotal());
   175	        m.put("discount", r.discount());
   176	        m.put("total", r.total());
   177	        m.put("status", r.status().name());
   178	        m.put("amountPaid", r.amountPaid());
   179	        m.put("refund", r.refund());
   180	        return m;
   181	    }
   182	
   183	    private static Map<String, Object> receiptView(Receipt d) {
   184	        Map<String, Object> m = new LinkedHashMap<>();
   185	        m.put("title", Receipt.TITLE);
   186	        m.put("reservationId", d.reservationId());
   187	        m.put("guestName", d.guestName());
   188	        m.put("guestCpf", d.guestCpf());
   189	        m.put("roomNumber", d.roomNumber());
   190	        m.put("roomType", d.roomType());
   191	        m.put("checkIn", d.checkIn().toString());
   192	        m.put("checkOut", d.checkOut().toString());
   193	        m.put("nights", d.nights());
   194	        m.put("subtotal", d.subtotal());
