     1	package br.com.marealta.service;
     2	
     3	import br.com.marealta.plan.Money;
     4	import java.math.BigDecimal;
     5	import java.time.LocalDate;
     6	import java.time.format.DateTimeFormatter;
     7	
     8	/** Comprovante de reserva (também usado como segunda via). */
     9	public record Receipt(long reservationId, String guestName, String guestCpf, int roomNumber, String roomType,
    10	                      LocalDate checkIn, LocalDate checkOut, int nights,
    11	                      BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
    12	
    13	    public static final String TITLE = "Comprovante de reserva";
    14	    private static final DateTimeFormatter BR_DATE = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    15	
    16	    public String text() {
    17	        StringBuilder sb = new StringBuilder();
    18	        sb.append(TITLE).append(" nº ").append(reservationId).append('\n');
    19	        sb.append("Hóspede: ").append(guestName).append(" (CPF ").append(formatCpf(guestCpf)).append(")\n");
    20	        sb.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
    21	        sb.append("Entrada: ").append(BR_DATE.format(checkIn)).append(" | Saída: ").append(BR_DATE.format(checkOut))
    22	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
    23	        sb.append("Diárias: ").append(Money.brl(subtotal)).append('\n');
    24	        if (discount.signum() > 0) {
    25	            sb.append("Desconto: ").append(Money.brl(discount)).append('\n');
    26	        }
    27	        sb.append("Total: ").append(Money.brl(total));
    28	        return sb.toString();
    29	    }
    30	
    31	    private static String formatCpf(String cpf) {
    32	        if (cpf.matches("\\d{11}")) {
    33	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." + cpf.substring(6, 9) + "-" + cpf.substring(9);
    34	        }
    35	        return cpf;
    36	    }
    37	}
=== src/main/java/br/com/marealta/service/ReportService.java
     1	package br.com.marealta.service;
     2	
     3	import br.com.marealta.db.Database;
     4	import br.com.marealta.db.Repository;
     5	import java.math.BigDecimal;
     6	import java.sql.*;
     7	import java.time.LocalDate;
     8	import java.time.YearMonth;
     9	
    10	public class ReportService {
    11	    private final Database db;
    12	
    13	    public ReportService(Database db) { this.db = db; }
    14	
    15	    public String occupancy(LocalDate night) {
    16	        return db.inTransaction(c -> {
    17	            StringBuilder sb = new StringBuilder("room,type,reservation,check_in,check_out\n");
    18	            int occupied = 0;
    19	            try (PreparedStatement ps = c.prepareStatement(
    20	                    "SELECT r.room_number, m.type, r.id, r.check_in, r.check_out FROM reservations r "
    21	                            + "JOIN rooms m ON m.number = r.room_number "
    22	                            + "WHERE r.status IN ('CONFIRMED','CHECKED_IN','CHECKED_OUT') "
    23	                            + "AND r.check_in <= ? AND r.check_out > ? ORDER BY r.room_number, r.id")) {
    24	                ps.setDate(1, Date.valueOf(night));
    25	                ps.setDate(2, Date.valueOf(night));
    26	                try (ResultSet rs = ps.executeQuery()) {
    27	                    while (rs.next()) {
    28	                        occupied++;
    29	                        sb.append(rs.getInt(1)).append(',').append(rs.getString(2)).append(',').append(rs.getLong(3))
    30	                                .append(',').append(rs.getDate(4).toLocalDate()).append(',')
    31	                                .append(rs.getDate(5).toLocalDate()).append('\n');
    32	                    }
    33	                }
    34	            }
    35	            int totalRooms = Repository.rooms(c).size();
    36	            return sb.append("total,").append(occupied).append('/').append(totalRooms).append('\n').toString();
    37	        });
    38	    }
    39	
    40	    public String revenue(YearMonth month) {
    41	        return db.inTransaction(c -> {
    42	            StringBuilder sb = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
    43	            BigDecimal sum = BigDecimal.ZERO.setScale(2);
    44	            try (PreparedStatement ps = c.prepareStatement(
    45	                    "SELECT id, room_number, check_in, check_out, status, amount_paid - COALESCE(refund, 0) AS amount "
    46	                            + "FROM reservations WHERE check_in >= ? AND check_in < ? "
    47	                            + "AND amount_paid - COALESCE(refund, 0) > 0 ORDER BY check_in, id")) {
    48	                ps.setDate(1, Date.valueOf(month.atDay(1)));
    49	                ps.setDate(2, Date.valueOf(month.plusMonths(1).atDay(1)));
    50	                try (ResultSet rs = ps.executeQuery()) {
    51	                    while (rs.next()) {
    52	                        BigDecimal amount = rs.getBigDecimal(6);
    53	                        sum = sum.add(amount);
    54	                        sb.append(rs.getLong(1)).append(',').append(rs.getInt(2)).append(',')
    55	                                .append(rs.getDate(3).toLocalDate()).append(',').append(rs.getDate(4).toLocalDate())
    56	                                .append(',').append(rs.getString(5)).append(',').append(amount.toPlainString()).append('\n');
    57	                    }
    58	                }
    59	            }
    60	            return sb.append("total,").append(sum.toPlainString()).append('\n').toString();
    61	        });
    62	    }
    63	}
