    14	public class ReservationService {
    15	    public record NewReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
    16	                                 LocalDate checkIn, LocalDate checkOut, int guests, RatePlan plan, String companyCode) {}
    17	
    18	    private final Database db;
    19	
    20	    public ReservationService(Database db) { this.db = db; }
    21	
    22	    public List<Room> rooms() {
    23	        return db.inTransaction(Repository::rooms);
    24	    }
    25	
    26	    public List<Message> messages() {
    27	        return db.inTransaction(Repository::messages);
    28	    }
    29	
    30	    public Reservation create(NewReservation n) {
