    14	public class ReservationService {
    15	    public record NewReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
    16	                                 LocalDate checkIn, LocalDate checkOut, int guests, RatePlan plan, String companyCode) {}
    17	
    18	    private final Database db;
    19	
    20	    public ReservationService(Database db) { this.db = db; }
    21	
    22	    public List<Room> rooms() {
    23	        return db.inTransaction(Repository::rooms);
    24	    }
    25	
    26	    public List<Message> messages() {
    27	        return db.inTransaction(Repository::messages);
    28	    }
    29	
    30	    public Reservation create(NewReservation n) {
    31	        return db.inTransaction(c -> {
    32	            Room room = Repository.lockRoom(c, n.roomNumber())
    33	                    .orElseThrow(() -> new ApiException(404, "ROOM_NOT_FOUND", "Quarto " + n.roomNumber() + " não existe"));
    34	            Quote quote = n.plan().quote(new QuoteRequest(room, n.checkIn(), n.checkOut(), n.companyCode()));
    35	            if (n.guests() > room.capacity()) {
    36	                throw new ApiException(422, "CAPACITY_EXCEEDED",
    37	                        "O quarto " + room.number() + " comporta no máximo " + room.capacity() + " hóspedes");
    38	            }
    39	            if (Repository.hasConflict(c, room.number(), n.checkIn(), n.checkOut())) {
    40	                throw new ApiException(409, "ROOM_UNAVAILABLE", "O quarto já está reservado em alguma das noites");
    41	            }
    42	            String company = n.plan() instanceof CorporatePlan ? n.companyCode() : null;
    43	            Reservation draft = new Reservation(0, room.number(), n.guestName(), n.guestEmail(), n.guestCpf(),
    44	                    n.checkIn(), n.checkOut(), n.guests(), n.plan().code(), company, quote.nights(),
    45	                    quote.subtotal(), quote.discount(), quote.total(), ReservationStatus.PENDING,
    46	                    Money.round(BigDecimal.ZERO), null);
    47	            long id = Repository.insert(c, draft);
    48	            return Repository.reservation(c, id, false).orElseThrow();
    49	        });
    50	    }
    51	
    52	    public Reservation get(long id) {
    53	        return db.inTransaction(c -> load(c, id, false));
    54	    }
    55	
    56	    public Reservation confirm(long id) {
    57	        return db.inTransaction(c -> {
    58	            Reservation r = load(c, id, true);
    59	            require(r, r.status() == ReservationStatus.PENDING, "Só é possível confirmar uma reserva pendente");
    60	            Repository.updateState(c, id, ReservationStatus.CONFIRMED, r.total(), null);
    61	            Reservation confirmed = load(c, id, false);
    62	            Receipt receipt = receipt(c, confirmed);
    63	            Repository.insertMessage(c, "EMAIL", confirmed.guestEmail(), "Reserva confirmada - Pousada Maré Alta",
    64	                    "Olá, " + confirmed.guestName() + "!\n\n"
    65	                            + "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n"
    66	                            + receipt.text() + "\n\n"
    67	                            + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
    68	                            + "Até breve!");
    69	            return confirmed;
    70	        });
    71	    }
    72	
    73	    public Reservation cancel(long id) {
    74	        return db.inTransaction(c -> {
    75	            Reservation r = load(c, id, true);
    76	            require(r, r.status() == ReservationStatus.PENDING || r.status() == ReservationStatus.CONFIRMED,
    77	                    "Só é possível cancelar antes do check-in");
    78	            RatePlan plan = planOf(r);
    79	            BigDecimal refund = Money.round(plan.refund(r.amountPaid()));
    80	            Repository.updateState(c, id, ReservationStatus.CANCELLED, r.amountPaid(), refund);
    81	            return load(c, id, false);
    82	        });
    83	    }
    84	
    85	    public Reservation checkIn(long id) {
    86	        return db.inTransaction(c -> {
    87	            Reservation r = load(c, id, true);
    88	            require(r, r.status() == ReservationStatus.CONFIRMED, "Só é possível fazer check-in de uma reserva confirmada");
    89	            Repository.updateState(c, id, ReservationStatus.CHECKED_IN, r.amountPaid(), r.refund());
    90	            return load(c, id, false);
    91	        });
    92	    }
    93	
    94	    public Receipt checkOut(long id) {
    95	        return db.inTransaction(c -> {
    96	            Reservation r = load(c, id, true);
    97	            require(r, r.status() == ReservationStatus.CHECKED_IN, "Só é possível fazer check-out após o check-in");
    98	            Repository.updateState(c, id, ReservationStatus.CHECKED_OUT, r.amountPaid(), r.refund());
    99	            return receipt(c, load(c, id, false));
   100	        });
   101	    }
   102	
   103	    public Receipt document(long id) {
   104	        return db.inTransaction(c -> {
   105	            Reservation r = load(c, id, false);
   106	            require(r, r.status().isPaid(), "A segunda via só existe para reserva paga");
   107	            return receipt(c, r);
   108	        });
   109	    }
   110	
   111	    private static Reservation load(Connection c, long id, boolean lock) throws SQLException {
   112	        return Repository.reservation(c, id, lock)
   113	                .orElseThrow(() -> new ApiException(404, "RESERVATION_NOT_FOUND", "Reserva " + id + " não existe"));
   114	    }
   115	
   116	    private static void require(Reservation r, boolean ok, String message) {
   117	        if (!ok) throw ApiException.notAllowed(message + " (situação atual: " + r.status() + ")");
   118	    }
   119	
   120	    private static RatePlan planOf(Reservation r) {
   121	        return RatePlans.find(r.ratePlan()).orElseThrow(() -> new IllegalStateException("Plano desconhecido: " + r.ratePlan()));
   122	    }
   123	
   124	    private static Receipt receipt(Connection c, Reservation r) throws SQLException {
   125	        Room room = Repository.room(c, r.roomNumber()).orElseThrow();
   126	        return new Receipt(r.id(), r.guestName(), r.guestCpf(), room.number(), room.type(), r.checkIn(), r.checkOut(),
   127	                r.nights(), r.subtotal(), r.discount(), r.total());
   128	    }
   129	}

