     1	package br.com.marealta.db;
     2	
     3	import com.zaxxer.hikari.HikariConfig;
     4	import com.zaxxer.hikari.HikariDataSource;
     5	import java.sql.Connection;
     6	import java.sql.SQLException;
     7	import java.sql.Statement;
     8	
     9	public class Database implements AutoCloseable {
    10	    private static final String SCHEMA = """
    11	            CREATE TABLE IF NOT EXISTS rooms (
    12	                number INT PRIMARY KEY,
    13	                type TEXT NOT NULL,
    14	                capacity INT NOT NULL,
    15	                nightly_rate NUMERIC(12,2) NOT NULL
    16	            );
    17	            CREATE TABLE IF NOT EXISTS reservations (
    18	                id BIGSERIAL PRIMARY KEY,
    19	                room_number INT NOT NULL REFERENCES rooms(number),
    20	                guest_name TEXT NOT NULL,
    21	                guest_email TEXT NOT NULL,
    22	                guest_cpf TEXT NOT NULL,
    23	                check_in DATE NOT NULL,
    24	                check_out DATE NOT NULL,
    25	                guests INT NOT NULL,
    26	                rate_plan TEXT NOT NULL,
    27	                company_code TEXT,
    28	                nights INT NOT NULL,
    29	                subtotal NUMERIC(12,2) NOT NULL,
    30	                discount NUMERIC(12,2) NOT NULL,
    31	                total NUMERIC(12,2) NOT NULL,
    32	                status TEXT NOT NULL,
    33	                amount_paid NUMERIC(12,2) NOT NULL DEFAULT 0,
    34	                refund NUMERIC(12,2)
    35	            );
    36	            CREATE INDEX IF NOT EXISTS idx_reservations_room ON reservations (room_number, check_in);
    37	            CREATE INDEX IF NOT EXISTS idx_reservations_check_in ON reservations (check_in);
    38	            CREATE TABLE IF NOT EXISTS messages (
    39	                id BIGSERIAL PRIMARY KEY,
    40	                channel TEXT NOT NULL,
    41	                recipient TEXT NOT NULL,
    42	                subject TEXT NOT NULL,
    43	                body TEXT NOT NULL
    44	            );
    45	            INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES
    46	                (101, 'STANDARD', 2, 249.90),
    47	                (102, 'STANDARD', 2, 249.90),
    48	                (201, 'DELUXE', 3, 389.90),
    49	                (202, 'DELUXE', 3, 389.90),
    50	                (301, 'SUITE', 4, 579.90)
    51	            ON CONFLICT (number) DO NOTHING;
    52	            """;
    53	
    54	    public interface TxWork<T> {
    55	        T run(Connection c) throws SQLException;
    56	    }
    57	
    58	    private final HikariDataSource ds;
    59	
    60	    public Database(String url, String user, String password) {
    61	        HikariConfig cfg = new HikariConfig();
    62	        cfg.setJdbcUrl(url);
    63	        cfg.setUsername(user);
    64	        cfg.setPassword(password);
    65	        cfg.setMaximumPoolSize(10);
    66	        cfg.setInitializationFailTimeout(-1); // o banco pode demorar a subir; o init abaixo tenta de novo
    67	        this.ds = new HikariDataSource(cfg);
    68	    }
    69	
    70	    /** Cria as tabelas (e os quartos) se ainda não existirem; espera o banco ficar disponível. */
    71	    public void init() {
    72	        long deadline = System.currentTimeMillis() + 60_000;
    73	        while (true) {
    74	            try {
    75	                inTransaction(c -> {
    76	                    try (Statement st = c.createStatement()) {
    77	                        // evita corrida se duas instâncias subirem juntas
    78	                        st.execute("SELECT pg_advisory_xact_lock(7070)");
    79	                        st.execute(SCHEMA);
    80	                    }
    81	                    return null;
    82	                });
    83	                return;
    84	            } catch (RuntimeException e) {
    85	                if (System.currentTimeMillis() > deadline) throw e;
    86	                try { Thread.sleep(1000); } catch (InterruptedException ie) { Thread.currentThread().interrupt(); throw e; }
    87	            }
    88	        }
    89	    }
    90	
    91	    public <T> T inTransaction(TxWork<T> work) {
    92	        try (Connection c = ds.getConnection()) {
    93	            c.setAutoCommit(false);
    94	            try {
    95	                T result = work.run(c);
    96	                c.commit();
    97	                return result;
    98	            } catch (Throwable t) {
    99	                c.rollback();
   100	                throw t;
   101	            }
   102	        } catch (SQLException e) {
   103	            throw new IllegalStateException("Erro de banco de dados: " + e.getMessage(), e);
   104	        }
   105	    }
   106	
   107	    @Override
   108	    public void close() { ds.close(); }
   109	}
