     9	import java.util.Optional;
    10	
    11	/** Acesso às tabelas; todos os métodos usam a conexão (transação) de quem chama. */
    12	public final class Repository {
    13	    private Repository() {}
    14	
    15	    private static final String RES_COLS = "id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, "
    16	            + "guests, rate_plan, company_code, nights, subtotal, discount, total, status, amount_paid, refund";
    17	
    18	    public static List<Room> rooms(Connection c) throws SQLException {
    19	        List<Room> out = new ArrayList<>();
    20	        try (Statement st = c.createStatement();
    21	             ResultSet rs = st.executeQuery("SELECT number, type, capacity, nightly_rate FROM rooms ORDER BY number")) {
    22	            while (rs.next()) out.add(room(rs));
    23	        }
    24	        return out;
    25	    }
    26	
    27	    /** Busca o quarto travando a linha, para serializar reservas concorrentes do mesmo quarto. */
    28	    public static Optional<Room> lockRoom(Connection c, int number) throws SQLException {
    29	        try (PreparedStatement ps = c.prepareStatement(
    30	                "SELECT number, type, capacity, nightly_rate FROM rooms WHERE number = ? FOR UPDATE")) {
    31	            ps.setInt(1, number);
    32	            try (ResultSet rs = ps.executeQuery()) {
    33	                return rs.next() ? Optional.of(room(rs)) : Optional.empty();
    34	            }
    35	        }
    36	    }
    37	
    38	    public static Optional<Room> room(Connection c, int number) throws SQLException {
    39	        try (PreparedStatement ps = c.prepareStatement(
    40	                "SELECT number, type, capacity, nightly_rate FROM rooms WHERE number = ?")) {
    41	            ps.setInt(1, number);
    42	            try (ResultSet rs = ps.executeQuery()) {
    43	                return rs.next() ? Optional.of(room(rs)) : Optional.empty();
    44	            }
    45	        }
    46	    }
    47	
    48	    public static boolean hasConflict(Connection c, int room, LocalDate in, LocalDate out) throws SQLException {
    49	        try (PreparedStatement ps = c.prepareStatement(
    50	                "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
    51	                        + "AND check_in < ? AND check_out > ? LIMIT 1")) {
    52	            ps.setInt(1, room);
    53	            ps.setDate(2, Date.valueOf(out));
    54	            ps.setDate(3, Date.valueOf(in));
    55	            try (ResultSet rs = ps.executeQuery()) {
    56	                return rs.next();
    57	            }
    58	        }
    59	    }
    60	
    61	    public static long insert(Connection c, Reservation r) throws SQLException {
    62	        try (PreparedStatement ps = c.prepareStatement(
    63	                "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, check_out, guests, "
    64	                        + "rate_plan, company_code, nights, subtotal, discount, total, status, amount_paid) "
    65	                        + "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) RETURNING id")) {
    66	            int i = 1;
    67	            ps.setInt(i++, r.roomNumber());
    68	            ps.setString(i++, r.guestName());
    69	            ps.setString(i++, r.guestEmail());
    70	            ps.setString(i++, r.guestCpf());
    71	            ps.setDate(i++, Date.valueOf(r.checkIn()));
    72	            ps.setDate(i++, Date.valueOf(r.checkOut()));
    73	            ps.setInt(i++, r.guests());
    74	            ps.setString(i++, r.ratePlan());
    75	            ps.setString(i++, r.companyCode());
    76	            ps.setInt(i++, r.nights());
    77	            ps.setBigDecimal(i++, r.subtotal());
    78	            ps.setBigDecimal(i++, r.discount());
    79	            ps.setBigDecimal(i++, r.total());
    80	            ps.setString(i++, r.status().name());
    81	            ps.setBigDecimal(i, r.amountPaid());
    82	            try (ResultSet rs = ps.executeQuery()) {
    83	                rs.next();
    84	                return rs.getLong(1);
    85	            }
    86	        }
    87	    }
    88	
    89	    public static Optional<Reservation> reservation(Connection c, long id, boolean lock) throws SQLException {
    90	        try (PreparedStatement ps = c.prepareStatement(
    91	                "SELECT " + RES_COLS + " FROM reservations WHERE id = ?" + (lock ? " FOR UPDATE" : ""))) {
    92	            ps.setLong(1, id);
    93	            try (ResultSet rs = ps.executeQuery()) {
    94	                return rs.next() ? Optional.of(reservation(rs)) : Optional.empty();
    95	            }
    96	        }
    97	    }
    98	
    99	    public static void updateState(Connection c, long id, ReservationStatus status, BigDecimal paid, BigDecimal refund)
   100	            throws SQLException {
   101	        try (PreparedStatement ps = c.prepareStatement(
   102	                "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
   103	            ps.setString(1, status.name());
   104	            ps.setBigDecimal(2, paid);
   105	            ps.setBigDecimal(3, refund);
   106	            ps.setLong(4, id);
   107	            ps.executeUpdate();
   108	        }
   109	    }
   110	
   111	    public static void insertMessage(Connection c, String channel, String to, String subject, String body)
   112	            throws SQLException {
   113	        try (PreparedStatement ps = c.prepareStatement(
   114	                "INSERT INTO messages (channel, recipient, subject, body) VALUES (?,?,?,?)")) {
   115	            ps.setString(1, channel);
   116	            ps.setString(2, to);
   117	            ps.setString(3, subject);
   118	            ps.setString(4, body);
   119	            ps.executeUpdate();
   120	        }
   121	    }
   122	
   123	    public static List<Message> messages(Connection c) throws SQLException {
   124	        List<Message> out = new ArrayList<>();
   125	        try (Statement st = c.createStatement();
   126	             ResultSet rs = st.executeQuery("SELECT id, channel, recipient, subject, body FROM messages ORDER BY id")) {
   127	            while (rs.next()) {
   128	                out.add(new Message(rs.getLong(1), rs.getString(2), rs.getString(3), rs.getString(4), rs.getString(5)));
   129	            }
   130	        }
   131	        return out;
   132	    }
   133	
   134	    private static Room room(ResultSet rs) throws SQLException {
   135	        return new Room(rs.getInt(1), rs.getString(2), rs.getInt(3), rs.getBigDecimal(4));
   136	    }
   137	
   138	    private static Reservation reservation(ResultSet rs) throws SQLException {
   139	        return new Reservation(rs.getLong(1), rs.getInt(2), rs.getString(3), rs.getString(4), rs.getString(5),
   140	                rs.getDate(6).toLocalDate(), rs.getDate(7).toLocalDate(), rs.getInt(8), rs.getString(9),
   141	                rs.getString(10), rs.getInt(11), rs.getBigDecimal(12), rs.getBigDecimal(13), rs.getBigDecimal(14),
   142	                ReservationStatus.valueOf(rs.getString(15)), rs.getBigDecimal(16), rs.getBigDecimal(17));
   143	    }
