    50	                (301, 'SUITE', 4, 579.90)
    51	            ON CONFLICT (number) DO NOTHING;
    52	            """;
    53	
    54	    public interface TxWork<T> {
    55	        T run(Connection c) throws SQLException;
    56	    }
    57	
    58	    private final HikariDataSource ds;
    59	
    60	    public Database(String url, String user, String password) {
    61	        HikariConfig cfg = new HikariConfig();
    62	        cfg.setJdbcUrl(url);
    63	        cfg.setUsername(user);
    64	        cfg.setPassword(password);
    65	        cfg.setMaximumPoolSize(10);
    66	        cfg.setInitializationFailTimeout(-1); // o banco pode demorar a subir; o init abaixo tenta de novo
    67	        this.ds = new HikariDataSource(cfg);
    68	    }
