    70	    /** Cria as tabelas (e os quartos) se ainda não existirem; espera o banco ficar disponível. */
    71	    public void init() {
    72	        long deadline = System.currentTimeMillis() + 60_000;
    73	        while (true) {
    74	            try {
    75	                inTransaction(c -> {
    76	                    try (Statement st = c.createStatement()) {
    77	                        // evita corrida se duas instâncias subirem juntas
    78	                        st.execute("SELECT pg_advisory_xact_lock(7070)");
    79	                        st.execute(SCHEMA);
    80	                    }
    81	                    return null;
    82	                });
    83	                return;
    84	            } catch (RuntimeException e) {
    85	                if (System.currentTimeMillis() > deadline) throw e;
    86	                try { Thread.sleep(1000); } catch (InterruptedException ie) { Thread.currentThread().interrupt(); throw e; }
    87	            }
