    91	    public <T> T inTransaction(TxWork<T> work) {
    92	        try (Connection c = ds.getConnection()) {
    93	            c.setAutoCommit(false);
    94	            try {
    95	                T result = work.run(c);
    96	                c.commit();
    97	                return result;
    98	            } catch (Throwable t) {
    99	                c.rollback();
   100	                throw t;
   101	            }
   102	        } catch (SQLException e) {
   103	            throw new IllegalStateException("Erro de banco de dados: " + e.getMessage(), e);
   104	        }
   105	    }
