     1	package br.com.marealta.plan;
     2	
     3	import br.com.marealta.model.Room;
     4	import java.math.BigDecimal;
     5	import java.time.LocalDate;
     6	
     7	abstract class AbstractRatePlan implements RatePlan {
     8	    private static final BigDecimal HIGH_SEASON = new BigDecimal("1.20");
     9	
    10	    /** Preço de uma noite: diária do quarto, com 20% a mais na alta temporada. */
    11	    static BigDecimal nightPrice(Room room, LocalDate night) {
    12	        BigDecimal rate = room.nightlyRate();
    13	        return Money.round(Season.isHigh(night) ? rate.multiply(HIGH_SEASON) : rate);
    14	    }
    15	
    16	    /** Soma das noites, cada uma já arredondada. */
    17	    static BigDecimal sumOfNights(QuoteRequest r) {
    18	        BigDecimal sum = BigDecimal.ZERO;
    19	        for (LocalDate d = r.checkIn(); d.isBefore(r.checkOut()); d = d.plusDays(1)) {
    20	            sum = sum.add(nightPrice(r.room(), d));
    21	        }
    22	        return Money.round(sum);
    23	    }
    24	
    25	    static Quote withDiscount(QuoteRequest r, String fraction) {
    26	        BigDecimal subtotal = sumOfNights(r);
    27	        return new Quote(r.nights(), subtotal, Money.percentOf(subtotal, fraction));
    28	    }
    29	
    30	    static BigDecimal full(BigDecimal paid) { return Money.round(paid); }
    31	}
