     1	package br.com.marealta.plan;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	
     6	public final class Money {
     7	    private Money() {}
     8	
     9	    /** Arredondamento para centavos, "meio para o par". */
    10	    public static BigDecimal round(BigDecimal v) {
    11	        return v.setScale(2, RoundingMode.HALF_EVEN);
    12	    }
    13	
    14	    public static BigDecimal of(String v) {
    15	        return round(new BigDecimal(v));
    16	    }
    17	
    18	    public static BigDecimal percentOf(BigDecimal amount, String fraction) {
    19	        return round(amount.multiply(new BigDecimal(fraction)));
    20	    }
    21	
    22	    /** Formata como "R$ 1.234,56". */
    23	    public static String brl(BigDecimal v) {
    24	        String plain = round(v).abs().toPlainString();
    25	        int dot = plain.indexOf('.');
    26	        String ints = plain.substring(0, dot);
    27	        StringBuilder sb = new StringBuilder();
    28	        for (int i = 0; i < ints.length(); i++) {
    29	            if (i > 0 && (ints.length() - i) % 3 == 0) sb.append('.');
    30	            sb.append(ints.charAt(i));
    31	        }
    32	        return (v.signum() < 0 ? "-R$ " : "R$ ") + sb + "," + plain.substring(dot + 1);
    33	    }
    34	}
