 9	import java.time.LocalDate;
10	import org.junit.jupiter.api.Test;
11	
12	class RatePlanTest {
13	    static final Room STANDARD = new Room(101, "STANDARD", 2, Money.of("249.90"));
14	    static final Room DELUXE = new Room(201, "DELUXE", 3, Money.of("389.90"));
15	
16	    static Quote quote(String plan, Room room, String in, String out, String company) {
17	        return RatePlans.find(plan).orElseThrow()
18	                .quote(new QuoteRequest(room, LocalDate.parse(in), LocalDate.parse(out), company));
19	    }
20	
21	    static void assertMoney(String expected, BigDecimal actual) {
22	        assertEquals(expected, actual.toPlainString());
23	    }
24	
25	    @Test
26	    void highSeasonNights() {
27	        Quote q = quote("STANDARD", STANDARD, "2027-07-10", "2027-07-12", null);
28	        assertMoney("599.76", q.subtotal());
29	        assertMoney("599.76", q.total());
30	        assertTrue(Season.isHigh(LocalDate.parse("2027-12-15")));
31	        assertFalse(Season.isHigh(LocalDate.parse("2027-12-14")));
32	        assertTrue(Season.isHigh(LocalDate.parse("2028-02-29")));
33	        assertFalse(Season.isHigh(LocalDate.parse("2027-03-01")));
34	    }
35	
36	    @Test
37	    void nonRefundable() {
38	        Quote q = quote("NON_REFUNDABLE", DELUXE, "2027-03-10", "2027-03-12", null);
39	        assertMoney("779.80", q.subtotal());
40	        assertMoney("116.97", q.discount());
41	        assertMoney("662.83", q.total());
42	        assertMoney("0.00", RatePlans.find("NON_REFUNDABLE").orElseThrow().refund(q.total()));
43	    }
44	
45	    @Test
46	    void corporate() {
47	        Quote q = quote("CORPORATE", DELUXE, "2027-03-10", "2027-03-12", "TECNOSUL");
48	        assertMoney("779.80", q.subtotal());
49	        assertMoney("93.58", q.discount());
50	        assertMoney("686.22", q.total());
51	        assertEquals(400, assertThrows(ApiException.class, () -> quote("CORPORATE", DELUXE, "2027-03-10", "2027-03-12", null)).status());
52	        assertEquals(400, assertThrows(ApiException.class, () -> quote("CORPORATE", DELUXE, "2027-03-10", "2027-03-12", "OUTRA")).status());
53	    }
54	
55	    @Test
56	    void weekendPackage() {
57	        Quote q = quote("WEEKEND_PACKAGE", DELUXE, "2027-03-12", "2027-03-14", null);
58	        assertMoney("820.00", q.subtotal());
59	        assertMoney("0.00", q.discount());
60	        assertMoney("410.00", RatePlans.find("WEEKEND_PACKAGE").orElseThrow().refund(q.total()));
61	        // pacote tem preço fechado também na alta temporada
62	        assertMoney("520.00", quote("WEEKEND_PACKAGE", STANDARD, "2027-07-09", "2027-07-11", null).total());
63	        assertThrows(ApiException.class, () -> quote("WEEKEND_PACKAGE", DELUXE, "2027-03-13", "2027-03-15", null));
64	        assertThrows(ApiException.class, () -> quote("WEEKEND_PACKAGE", DELUXE, "2027-03-12", "2027-03-15", null));
65	    }
66	
67	    @Test
68	    void longStay() {
69	        Quote q = quote("LONG_STAY", STANDARD, "2027-03-01", "2027-03-08", null);
70	        assertMoney("1749.30", q.subtotal());
71	        assertMoney("174.93", q.discount());
72	        assertMoney("1574.37", q.total());
73	        assertThrows(ApiException.class, () -> quote("LONG_STAY", STANDARD, "2027-03-01", "2027-03-07", null));
74	    }
75	
76	    @Test
77	    void receiptText() {
78	        Receipt r = new Receipt(7, "Carla Dias", "111.222.333-44", 201, "DELUXE", LocalDate.parse("2027-03-10"),
79	                LocalDate.parse("2027-03-12"), 2, Money.of("779.80"), Money.of("0"), Money.of("779.80"));
80	        assertEquals("""
81	                Comprovante de reserva nº 7
82	                Hóspede: Carla Dias (CPF 111.222.333-44)
83	                Quarto: 201 (DELUXE)
84	                Entrada: 10/03/2027 | Saída: 12/03/2027 | 2 diárias
85	                Diárias: R$ 779,80
86	                Total: R$ 779,80""", r.text());
87	        assertEquals("R$ 1.234,56", Money.brl(Money.of("1234.56")));
88	        assertEquals("R$ 1.749.300,00", Money.brl(Money.of("1749300")));
89	    }
90	}

